def calc(expr: str) -> int | str:
    import re

    # Tokenize: numbers, operators, parentheses
    token_pattern = re.compile(r'\d+|[\+\-\*/%\^\(\)]')
    tokens = token_pattern.findall(expr)
    # Remove spaces implicitly by regex (they are not matched)

    n = len(tokens)
    pos = 0

    class EvalError(Exception):
        pass

    def peek():
        return tokens[pos] if pos < n else None

    def consume(expected=None):
        nonlocal pos
        if pos >= n:
            raise EvalError()
        tok = tokens[pos]
        if expected and tok != expected:
            raise EvalError()
        pos += 1
        return tok

    # Truncating division toward zero
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise EvalError()
        q = abs(a) // abs(b)
        return q if a * b >= 0 else -q

    # Modulo as defined
    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise EvalError()
        q = trunc_div(a, b)
        return a - b * q

    # Grammar according to precedence:
    # expr -> add_sub
    # add_sub -> mul_div ((+|-) mul_div)*
    # mul_div -> unary (( * | / | % ) unary)*
    # unary -> ('-')* power
    # power -> primary ( ^ power )?
    # primary -> number | '(' expr ')'

    def parse_expr() -> int:
        left = parse_add_sub()
        return left

    def parse_add_sub() -> int:
        left = parse_mul_div()
        while True:
            op = peek()
            if op == '+' or op == '-':
                consume()
                right = parse_mul_div()
                if op == '+':
                    left = left + right
                else:
                    left = left - right
            else:
                break
        return left

    def parse_mul_div() -> int:
        left = parse_unary()
        while True:
            op = peek()
            if op in ('*', '/', '%'):
                consume()
                right = parse_unary()
                if op == '*':
                    left = left * right
                elif op == '/':
                    left = trunc_div(left, right)
                else:  # '%'
                    left = trunc_mod(left, right)
            else:
                break
        return left

    def parse_unary() -> int:
        # Count consecutive '-'
        minus_count = 0
        while peek() == '-':
            consume('-')
            minus_count += 1
        val = parse_power()
        if minus_count % 2 == 1:
            val = -val
        return val

    def parse_power() -> int:
        left = parse_primary()
        if peek() == '^':
            consume('^')
            right = parse_power()          # right‑associative
            if right < 0:
                raise EvalError()
            # Python's pow handles 0**0 as 1, which matches spec
            left = pow(left, right)
        return left

    def parse_primary() -> int:
        tok = peek()
        if tok is None:
            raise EvalError()
        if tok == '(':
            consume('(')
            val = parse_expr()
            if peek() != ')':
                raise EvalError()
            consume(')')
            return val
        if re.fullmatch(r'\d+', tok):
            consume()
            return int(tok)
        # Should not happen because input is syntactically valid
        raise EvalError()

    try:
        result = parse_expr()
        if pos != n:  # extra tokens
            raise EvalError()
        return result
    except EvalError:
        return "error"
